"""Black-box PETG dispatch test using the pinned Farm Lab's disposable project."""

import printstash_http as lab
from farm_observer import ingest


def ingest_petg(app):
    gcode = (
        "; generated by OrcaSlicer\n; filament_type = PETG\n"
        "; estimated printing time (normal mode) = 60s\nG90\nG28\n"
        + "G1 X10 Y10 F1800\nG4 P2000\n" * 30
        + "M400\n"
    )
    return ingest(app, "coupon.gcode", gcode.encode())


def check_routing(app, klipper, bambu):
    app.setup()
    ids = []
    for device in (klipper, bambu):
        lab.wait_for(
            device.status,
            lambda live: live["state"] == "ready",
            90,
            "startup",
            lab.native_summary,
        )
        fields = lab.registration(device, app)
        row = app.post(
            "/printers",
            {
                **fields,
                "name": device.config["name"],
                "provider_material_sync_enabled": device is bambu,
            },
        )
        ids.append(row["id"])
        lab.wait_for(
            lambda printer_id=row["id"]: app.get(f"/printers/{printer_id}/status"),
            lambda data: data["printer"]["status"] == "ready",
            45,
            "PrintStash readiness",
            lambda data: data["printer"]["status"],
        )

    manual = app.call(
        "PUT",
        f"/printers/{ids[0]}/material-state/manual",
        {
            "tools": [{"tool_key": "tool0", "label": "Extruder"}],
            "slots": [
                {
                    "slot_key": "feed",
                    "label": "Spool",
                    "tool_key": "tool0",
                    "state": "loaded",
                    "material_type": "PLA",
                }
            ],
        },
    )
    lab.require(
        any(
            s["material_type"] == "PLA" and s["state"] == "loaded"
            for s in manual["slots"]
        ),
        f"Manual inventory: {manual['slots']}",
    )
    tray = {"material": "PETG", "color": "#008080"}
    bambu.material({"units": [[{}, tray, {}, {}]], "external": {}, "active": 1})
    lab.wait_for(
        bambu.status,
        lambda live: live.get("material", {}).get("units") == [[{}, tray, {}, {}]],
        20,
        "native AMS update",
        lambda live: live.get("material"),
    )
    lab.wait_for(
        lambda: app.get(f"/printers/{ids[1]}/material-state")["slots"],
        lambda slots: any(
            s["source"] == "bambu_ams"
            and s["state"] == "loaded"
            and s["material_type"] == "PETG"
            and s["color_hex"] == tray["color"]
            for s in slots
        ),
        45,
        "PrintStash MQTT AMS update",
    )

    file_id = ingest_petg(app)

    def compatible():
        return app.post(
            "/fleet/compatibility", {"file_id": file_id, "printer_ids": ids}
        )

    lab.wait_for(
        compatible,
        lambda data: (
            any(r["material_type"] == "PETG" for r in data["requirements"])
            and {p["printer_id"]: p["verdict"] for p in data["printers"]}
            == {ids[0]: "mismatch", ids[1]: "compatible"}
        ),
        60,
        "PETG compatibility",
    )

    # Only the dispatcher can transfer or start this file. No target is named.
    job = app.post("/fleet/queue", {"file_id": file_id, "strategy": "least_busy"})

    def queued():
        return next(
            (row for row in app.get("/fleet/queue") if row["id"] == job["id"]), {}
        )

    assigned = lab.wait_for(
        queued,
        lambda row: row.get("state") in {"started", "printing"},
        100,
        "PrintStash queue dispatch",
    )
    lab.require(
        assigned["printer_id"] == ids[1] and assigned["file_id"] == file_id,
        f"Unexpected dispatch: {assigned}",
    )
    filename = lab.basename(assigned["remote_filename"])
    native = lab.wait_for(
        bambu.status,
        lambda live: (
            live["state"] == "printing"
            and lab.basename(live["file"]) == filename
            and live["progress"] > 0
        ),
        40,
        "native Bambu job",
        lab.native_summary,
    )
    for device in (klipper, bambu):
        inventory = [lab.basename(item["path"]) for item in device.files()]
        present = filename in inventory
        lab.require(
            present == (device is bambu),
            f"Unexpected inventory on {device.kind}: {inventory}",
        )
    idle = klipper.status()
    lab.require(
        idle["state"] == "ready" and lab.basename(idle["file"]) != filename,
        f"Unexpected native Klipper job: {lab.native_summary(idle)}",
    )
    print(
        f"mixed-farm PASS: queue #{job['id']} -> Bambu #{ids[1]}, native {lab.native_summary(native)}; "
        f"Klipper #{ids[0]} {idle['state']}, file absent",
        flush=True,
    )


def observe():
    from devices import DeviceError, load_pool

    devices = load_pool("/test-pool.json")
    app = lab.App()
    try:
        check_routing(app, devices["klipper-spare-1"], devices["bambu-spare-1"])
    except (
        lab.Failure,
        DeviceError,
        OSError,
        KeyError,
        ValueError,
        TypeError,
    ) as error:
        print(f"mixed-farm FAIL: {app.redact(str(error))}", flush=True)
        for name, device in devices.items():
            print(name, lab.native_summary(device.status()), flush=True)
        return 1
    return 0
